import { createMemo, Show, type Component } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";

import { type PlotTooltipBaseProps } from "./helpers.js";

const ARCHEOLOGY_CONSTRUCTIBLE_TYPES = ["IMPROVEMENT_RUINS", "BUILDING_MUSEUM", "BUILDING_UNIVERSITY"];

interface ArcheologyTooltipData {
	titleText: string;
	descriptionText: string;
}

function getConstructibleInfo(construct: ComponentID): ConstructibleDefinition | undefined {
	const instance = Constructibles.getByComponentID(construct);
	if (!instance) {
		return undefined;
	}

	return GameInfo.Constructibles.lookup(instance.type) ?? undefined;
}

/**
 * Gets the archeology tooltip display data for the given plot coordinates.
 */
export function getArcheologyData(plotCoord: float2): ArcheologyTooltipData | undefined {
	const constructibles = MapConstructibles.getConstructibles(plotCoord.x, plotCoord.y);
	let constructibleInfo: ConstructibleDefinition | undefined;

	for (const construct of constructibles) {
		const info = getConstructibleInfo(construct);
		if (info && ARCHEOLOGY_CONSTRUCTIBLE_TYPES.includes(info.ConstructibleType)) {
			constructibleInfo = info;
		}
	}

	const isNaturalWonder = GameplayMap.isNaturalWonder(plotCoord.x, plotCoord.y);
	if (!constructibleInfo && !isNaturalWonder) {
		return undefined;
	}

	if (constructibleInfo?.ConstructibleType === "IMPROVEMENT_RUINS") {
		return {
			titleText: "LOC_PLOT_TOOLTIP_EXCAVATE_TITLE",
			descriptionText: "LOC_PLOT_TOOLTIP_EXCAVATE_RUINS_DESCRIPTION",
		};
	}

	if (isNaturalWonder) {
		return {
			titleText: "LOC_PLOT_TOOLTIP_STUDY_NATURAL_WONDER",
			descriptionText: "LOC_PLOT_TOOLTIP_NATURAL_WONDER_RESEARCH_DESCRIPTION",
		};
	}

	if (
		constructibleInfo?.ConstructibleType === "BUILDING_MUSEUM" ||
		constructibleInfo?.ConstructibleType === "BUILDING_UNIVERSITY"
	) {
		const research =
			Players.get(GameContext.localPlayerID)?.Culture?.getContinentResearchStatus(
				GameplayMap.getContinentType(plotCoord.x, plotCoord.y),
			) ?? "";
		return {
			titleText: "LOC_PLOT_TOOLTIP_RESEARCH_TITLE",
			descriptionText: research,
		};
	}

	return undefined;
}

/** Props for the ArcheologyPlotTooltipContent component */
export type ArcheologyPlotTooltipContentProps = PlotTooltipBaseProps;

/**
 * Determines whether the archeology tooltip has content to show at the given plot coordinates.
 * Returns true if the plot has ruins, a museum, a university, or is a natural wonder.
 */
export function hasArcheologyData(plotCoord: float2): boolean {
	return getArcheologyData(plotCoord) !== undefined;
}

/**
 * Content component for the archeology plot tooltip.
 * TODO: Implement the full content rendering.
 */
export const ArcheologyPlotTooltipContent: Component<ArcheologyPlotTooltipContentProps> = (props) => {
	const data = createMemo(() => getArcheologyData(props.plotCoord));

	return (
		<Show when={data()}>
			{(info) => (
				<div class="flex flex-col text-accent-2 max-w-96">
					<div class="flex flex-row justify-left text-sm font-bold tooltip-title">
						<L10n.Stylize text={info().titleText} />
					</div>
					<Show when={info().descriptionText}>
						<L10n.Stylize
							class="flex flex-col justify-around text-sm"
							text={info().descriptionText}
						/>
					</Show>
				</div>
			)}
		</Show>
	);
};
